    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  const fee = lateFee(draft, '2025-10-20');
  assert.equal(fee, 0);
});

test('lateFee returns 0 if invoice is paid', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
  }).value;

  let invoice = issueInvoice(draft, []).value;
  const r = recordPayment(invoice, { amount: 5748, date: '2025-10-20' });
  const paid = r.value;

  const fee = lateFee(paid, '2025-10-20');
  assert.equal(fee, 0);
});

test('lateFee returns 0 if not overdue (due date in future)', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const invoice = issueInvoice(draft, []).value;
  // dueDate: 2025-10-15

  const fee = lateFee(invoice, '2025-10-10');
  assert.equal(fee, 0);
});

test('lateFee returns 0 if due date equals asOf', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const invoice = issueInvoice(draft, []).value;
  // dueDate: 2025-10-15

  const fee = lateFee(invoice, '2025-10-15');
  assert.equal(fee, 0);
});

test('lateFee calculates 0.04% per day overdue', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const invoice = issueInvoice(draft, []).value;
  // dueDate: 2025-10-15, asOf: 2025-10-16 (1 day overdue)
  // amount due: 5748 cents
  // fee: 5748 * 0.04% * 1 = 5748 * 0.0004 = 2.2992 -> 2 cents

  const fee = lateFee(invoice, '2025-10-16');
  assert.equal(fee, 2);
});

test('lateFee accumulates over multiple days', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const invoice = issueInvoice(draft, []).value;
  // dueDate: 2025-10-15, asOf: 2025-10-20 (5 days overdue)
  // amount due: 5748 cents
  // fee: 5748 * 0.04% * 5 = 5748 * 0.002 = 11.496 -> 11 cents

  const fee = lateFee(invoice, '2025-10-20');
  assert.equal(fee, 11);
});

test('lateFee based on amount due, not full invoice total', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  let invoice = issueInvoice(draft, []).value;
  const r = recordPayment(invoice, { amount: 2000, date: '2025-10-15' });
  const partial = r.value;

  // Total: 5748, after payment of 2000: amount due = 3748
  // dueDate: 2025-10-15, asOf: 2025-10-16 (1 day overdue)
  // fee: 3748 * 0.04% * 1 = 3748 * 0.0004 = 1.4992 -> 1 cent

  const fee = lateFee(partial, '2025-10-16');
  assert.equal(fee, 1);
});

test('lateFee works for partially_paid invoices', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  let invoice = issueInvoice(draft, []).value;
  const r = recordPayment(invoice, { amount: 2000, date: '2025-10-15' });
  const partial = r.value;

  assert.equal(partial.status, 'partially_paid');

  const fee = lateFee(partial, '2025-10-20');
  assert.ok(fee > 0);
});

test('lateFee returns 0 for null or undefined invoice', () => {
  assert.equal(lateFee(null, '2025-10-20'), 0);
  assert.equal(lateFee(undefined, '2025-10-20'), 0);
});

test('lateFee with large overdue period', () => {
  const draft = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const invoice = issueInvoice(draft, []).value;
  // dueDate: 2025-10-15, asOf: 2025-11-15 (31 days overdue)
  // amount due: 5748 cents
  // fee: 5748 * 0.04% * 31 = 5748 * 0.0124 = 71.2752 -> 71 cents

  const fee = lateFee(invoice, '2025-11-15');
  assert.equal(fee, 71);
});

